fn multi_agent_plan_role(payload: &JsonValue) -> Option<&str> {
    payload
        .get("metadata")
        .and_then(JsonValue::as_object)
        .and_then(|metadata| {
            metadata
                .get("multiAgentPlan")
                .or_else(|| metadata.get("multi_agent_plan"))
        })
        .and_then(JsonValue::as_object)
        .and_then(|plan| plan.get("role"))
        .and_then(JsonValue::as_str)
}

fn is_multi_agent_lead_continuation_payload(payload: &JsonValue) -> bool {
    multi_agent_plan_role(payload)
        .map(|role| role.trim().eq_ignore_ascii_case("lead_continuation"))
        .unwrap_or(false)
}

fn is_multi_agent_worker_payload(payload: &JsonValue) -> bool {
    multi_agent_plan_role(payload)
        .map(|role| role.trim().eq_ignore_ascii_case("worker"))
        .unwrap_or(false)
}

fn should_persist_codex_conversation_thread(
    payload: &JsonValue,
    job_conversation_id: Option<Uuid>,
    runtime_is_browser_session: bool,
    expects_generic_mcp_tool_execution: bool,
) -> bool {
    should_persist_codex_conversation_thread_with_structured_persistence(
        payload,
        job_conversation_id,
        runtime_is_browser_session,
        expects_generic_mcp_tool_execution,
        env_bool("CODEX_PERSIST_STRUCTURED_CONVERSATION_THREAD")
            .unwrap_or(DEFAULT_PERSIST_STRUCTURED_CONVERSATION_THREAD),
    )
}

fn should_persist_codex_conversation_thread_for_execution(
    payload: &JsonValue,
    job_conversation_id: Option<Uuid>,
    runtime_is_browser_session: bool,
    expects_generic_mcp_tool_execution: bool,
    explicit_personal_browser_execution: bool,
) -> bool {
    !explicit_personal_browser_execution
        && should_persist_codex_conversation_thread(
            payload,
            job_conversation_id,
            runtime_is_browser_session,
            expects_generic_mcp_tool_execution,
        )
}

fn should_persist_codex_conversation_thread_with_structured_persistence(
    payload: &JsonValue,
    job_conversation_id: Option<Uuid>,
    runtime_is_browser_session: bool,
    expects_generic_mcp_tool_execution: bool,
    persist_structured_conversations: bool,
) -> bool {
    let has_conversation = job_conversation_id.is_some()
        || payload
            .get("conversation_id")
            .and_then(JsonValue::as_str)
            .map(|value| !value.trim().is_empty())
            .unwrap_or(false);
    if !has_conversation {
        return false;
    }

    if is_multi_agent_lead_continuation_payload(payload) {
        return false;
    }

    if runtime_is_browser_session || expects_generic_mcp_tool_execution {
        return true;
    }

    persist_structured_conversations
}

fn restored_provider_thread_available(
    provider_state: Option<&JsonValue>,
    browser_mode: bool,
) -> bool {
    let history_replay_required =
        provider_state_bool(provider_state, "historyReplayRequired").unwrap_or(false);
    if history_replay_required {
        return false;
    }

    let thread_key = if browser_mode {
        "browserThreadId"
    } else {
        "defaultThreadId"
    };

    provider_state_string(provider_state, thread_key)
        .or_else(|| provider_state_string(provider_state, "threadId"))
        .is_some()
}

/// The controller attaches the previous run's provider state when it enqueues a job, whichever
/// runtime later leases it. After a restart, or on a fresh runtime, the thread that state names
/// is often not restorable here, and Codex then quietly starts an empty thread. The prompt lane
/// and the contextual-instruction suppression are both chosen from this state before Codex
/// tries, so a state that still claims a restored thread would send the compact reminder to a
/// model with no history, no workspace memory snapshot and no skills catalog. Such a state is
/// marked for history replay so the turn gets the full lane. The second value says whether the
/// state was marked.
fn provider_conversation_state_for_this_runtime(
    state: Option<JsonValue>,
    browser_mode: bool,
) -> (Option<JsonValue>, bool) {
    let Some(mut state) = state else {
        return (None, false);
    };
    let claims_restored_thread = provider_state_claims_restored_thread(Some(&state))
        || restored_provider_thread_available(Some(&state), browser_mode);
    if !claims_restored_thread
        || provider_thread_restorable_on_this_runtime(Some(&state), browser_mode)
    {
        return (Some(state), false);
    }
    let Some(map) = state.as_object_mut() else {
        return (Some(state), false);
    };
    map.insert("historyReplayRequired".to_string(), JsonValue::Bool(true));
    (Some(state), true)
}

/// Whether the prompt these metrics describe replayed conversation turns. Team planning and
/// lead continuations leave the history out even when a replay is requested, and MCP task
/// prompts have no conversation context, so only a prompt that carried turns counts.
fn prompt_context_replayed_history(prompt_context: &JsonValue) -> bool {
    prompt_metric_bool(prompt_context, "historyReplayRequired")
        && prompt_context
            .get("includedTurns")
            .and_then(JsonValue::as_u64)
            .is_some_and(|turns| turns > 0)
}

/// Codex keeps `historyReplayRequired` set after a run that could not restore its thread,
/// because that run's prompt was normally built before the loss was known and carried no
/// history. When this run's prompt did replay the history, as it does once
/// `provider_conversation_state_for_this_runtime` has spotted a lost thread, the fresh thread
/// already holds it. Keeping the flag would make the next turn, whose new rollout resumes,
/// send the history, workspace snapshot and skills catalog into that thread a second time.
/// The flag is shared by the default and browser threads, so it stays set while the other
/// thread still lacks the history.
///
/// Codex recomputes the flag from both modes' `*ThreadRestoreFailed` fields on every run it
/// saves, so this mode's field is cleared too. Left set, the next run in the other mode would
/// raise the flag again for a thread that already holds the history. The
/// `*ThreadRestoreSource` and `lastThreadRestoreSource` fields still record the failed restore.
fn provider_conversation_state_after_history_replay(
    state: Option<JsonValue>,
    prompt_replayed_history: bool,
    browser_mode: bool,
) -> Option<JsonValue> {
    let mut state = state?;
    let (restore_failed_key, other_restore_failed_key) = if browser_mode {
        ("browserThreadRestoreFailed", "defaultThreadRestoreFailed")
    } else {
        ("defaultThreadRestoreFailed", "browserThreadRestoreFailed")
    };
    let started_fresh_thread =
        provider_state_bool(Some(&state), restore_failed_key).unwrap_or(false);
    if !prompt_replayed_history || !started_fresh_thread {
        return Some(state);
    }
    let other_thread_lacks_history =
        provider_state_bool(Some(&state), other_restore_failed_key).unwrap_or(false);
    if let Some(map) = state.as_object_mut() {
        map.insert(restore_failed_key.to_string(), JsonValue::Bool(false));
        map.insert(
            "historyReplayRequired".to_string(),
            JsonValue::Bool(other_thread_lacks_history),
        );
    }
    Some(state)
}

/// The provider state a Codex run saves for the next turn. The first attempt and the retry
/// both build it here, so the replay flag is decided in one place that tests can reach.
/// `run_prompt` is the prompt the run sent, `prompt` is the first attempt's prompt, and
/// `prompt_context` holds the metrics the run reports. A retry copies those metrics from the
/// first attempt, so they still say the history was replayed after a missing-final recovery
/// rebuilt its prompt from the latest request alone. The prompt text decides instead: every
/// retry that keeps the history resends the whole first prompt ahead of its own
/// instructions, and the first attempt sent that prompt itself.
fn provider_conversation_state_to_save(
    output: &CodexRunOutput,
    run_prompt: &str,
    prompt: &str,
    prompt_context: &JsonValue,
    browser_mode: bool,
) -> Option<JsonValue> {
    provider_conversation_state_after_history_replay(
        output.provider_conversation_state.clone(),
        run_prompt.starts_with(prompt) && prompt_context_replayed_history(prompt_context),
        browser_mode,
    )
}

fn broad_contextual_instruction_suppression_reason(
    job: &LeaseJob,
    _prompt_text: &str,
    scoped_worker_has_precollected_observations: bool,
    provider_conversation_state_for_run: Option<&JsonValue>,
    runtime_is_browser_session: bool,
    expects_direct_workspace_file_changes: bool,
) -> Option<&'static str> {
    if scoped_worker_has_precollected_observations {
        return Some("scoped_worker_preobserved");
    }
    if is_multi_agent_worker_job(job) {
        return Some("focused_multi_agent_worker_lane");
    }
    if is_multi_agent_lead_continuation_job(job) {
        return Some("focused_multi_agent_lead_continuation");
    }
    if is_explicit_team_planning_job(job) {
        return Some("focused_team_planning_skill_snapshot");
    }
    if !is_multi_agent_lead_continuation_job(job)
        && !is_multi_agent_worker_job(job)
        && job_requests_cross_chat_context_lookup(job)
    {
        return Some("focused_cross_chat_context_lookup");
    }
    if restored_provider_thread_available(
        provider_conversation_state_for_run,
        runtime_is_browser_session,
    ) {
        return Some("stateful_provider_thread_restored");
    }
    if expects_direct_workspace_file_changes {
        // The direct workspace-write lane is reserved for turns whose structured runtime
        // expectations require file changes. These turns already carry a compact contract
        // and skip the workspace memory snapshot; the skills catalog and AGENTS.md
        // scaffolding were most of the measured prompt and aggravate
        // reasoning-exhausted missing-final turns. Turns 2+ are already suppressed via the
        // restored-thread arm above; this extends the trim to attempt 1, matching the
        // recovery retry — accepting that the broad catalog is never seeded into these
        // conversations (the prompt names only the few workflow skills that match the
        // request strongly; see `format_skill_hints`). Instafy-curated context (INSTAFY.md snapshots, context cards,
        // pinned skill snapshots) is unaffected.
        return Some("focused_direct_workspace_write");
    }
    None
}

// Browser and MCP turns keep the broad catalog: their workflow behavior is skill-driven.
fn direct_write_broad_context_suppression_eligible(
    runtime_expectations: RuntimeJobExpectations,
    runtime_is_browser_session: bool,
) -> bool {
    runtime_expectations.workspace_file_changes
        && !runtime_is_browser_session
        && !runtime_expectations.generic_mcp_tool_execution
}

fn env_bool(key: &str) -> Option<bool> {
    let raw = env::var(key).ok()?;
    let normalized = raw.trim().to_ascii_lowercase();
    match normalized.as_str() {
        "1" | "true" | "yes" | "on" => Some(true),
        "0" | "false" | "no" | "off" => Some(false),
        _ => None,
    }
}

#[derive(Clone)]
struct TerminalSession {
    session_id: String,
    stdin: Arc<AsyncMutex<tokio::process::ChildStdin>>,
    child: Arc<AsyncMutex<tokio::process::Child>>,
    output: Arc<AsyncMutex<String>>,
    command_lock: Arc<AsyncMutex<()>>,
    workspace_dir: PathBuf,
}

enum TerminalCommandAction {
    Start,
    Stop,
    Status,
    Write(String),
    Run(String),
}

/// What the skills lane produced before the model turn of a `--start` import or a
/// `/skills start`: the report already streamed (when streaming was active) and the
/// artifacts to merge into the final execution.
struct SkillsKickoff {
    messages: Vec<JobMessage>,
    artifacts: Vec<JsonValue>,
    names: Vec<String>,
}

/// Fold the skills lane report into a model execution's messages so a model failure after a
/// successful import cannot lose the "Imported ..." report. When streaming is active the
/// report was already sent through the progress channel and streamed executions skip
/// `messages`. The lane artifacts are not handled here: they join the run's artifact list as
/// soon as it exists (see `skills_kickoff_artifacts`) so every failure path carries them.
fn merge_skills_kickoff_into_execution(
    kickoff: Option<SkillsKickoff>,
    streaming_active: bool,
    messages: Vec<JobMessage>,
) -> Vec<JobMessage> {
    let Some(kickoff) = kickoff else {
        return messages;
    };
    if streaming_active {
        return messages;
    }
    let mut merged = kickoff.messages;
    merged.extend(messages);
    merged
}

/// The `skills/import` artifacts of a pending kickoff, to prepend to a run's artifact list the
/// moment it is built so a `JobFailureWithArtifacts` after the import still records what was
/// written.
fn skills_kickoff_artifacts(kickoff: Option<&SkillsKickoff>) -> Vec<JsonValue> {
    kickoff
        .map(|kickoff| kickoff.artifacts.clone())
        .unwrap_or_default()
}

/// The lane name a skills lane checkpoint records on its `origin/apply` artifact.
const SKILLS_IMPORT_LANE: &str = "skills/import";

/// The lane name a write-scoped worker's checkpoint records on its
/// `origin/apply` artifact.
const WRITE_SCOPED_WORKER_LANE: &str = "multi-agent/write-scoped-worker";

/// Save the files a write-scoped worker wrote through the same protected
/// checkpoint a model turn's files take. The worker returns before any turn
/// checkpoint runs, so without this its files would reach canonical history
/// only through a stop's flush, as unsaved work.
async fn checkpoint_write_scoped_worker(
    mut execution: JobExecution,
    checkpoint: workspace_commit::LaneCheckpoint<'_>,
    files: &[CodexFileDescriptor],
) -> JobExecution {
    let (artifacts, not_saved) =
        workspace_commit::checkpoint_lane_files_with_report(checkpoint, files).await;
    execution.artifacts.extend(artifacts);
    save_report::append_not_saved(&mut execution.summary, &not_saved);
    execution
}

/// What the job does after the skills lane ran.
enum SkillsLaneStep {
    /// The lane finished the job.
    Finished(JobExecution),
    /// A model turn runs next with this prompt, and the kickoff joins its execution.
    Kickoff {
        prompt: String,
        kickoff: SkillsKickoff,
    },
}

/// Settle the skills lane's outcome. A kickoff's import report is streamed first. The files an
/// import wrote, with or without `--start`, then go to the protected checkpoint, and its
/// artifacts join the lane's own.
async fn settle_skills_lane_outcome(
    outcome: skills::SkillsLaneOutcome,
    checkpoint: workspace_commit::LaneCheckpoint<'_>,
) -> SkillsLaneStep {
    match outcome {
        skills::SkillsLaneOutcome::Execution(execution) => SkillsLaneStep::Finished(execution),
        skills::SkillsLaneOutcome::Installed {
            mut execution,
            files,
        } => {
            execution
                .artifacts
                .extend(workspace_commit::checkpoint_lane_files(checkpoint, &files).await);
            SkillsLaneStep::Finished(execution)
        }
        skills::SkillsLaneOutcome::Kickoff {
            report,
            mut artifacts,
            names,
            prompt,
            files,
        } => {
            let mut messages = Vec::new();
            if let Some(report) = report {
                if let Some(sender) = checkpoint.progress_sender.as_ref() {
                    let _ = sender.send(report.clone());
                }
                messages.push(report);
            }
            artifacts.extend(workspace_commit::checkpoint_lane_files(checkpoint, &files).await);
            SkillsLaneStep::Kickoff {
                prompt,
                kickoff: SkillsKickoff {
                    messages,
                    artifacts,
                    names,
                },
            }
        }
    }
}

async fn run_agents_memory_snapshot(
    workspace_dir: &Path,
    progress_sender: Option<JobMessageSender>,
) -> Option<String> {
    let script_path = workspace_dir.join(learn::AGENTS_SCRIPT_FILENAME);
    if !script_path.exists() {
        return None;
    }

    if let Some(sender) = progress_sender.as_ref() {
        let _ = sender.send(JobMessage {
            content: format!("python {}", learn::AGENTS_SCRIPT_FILENAME),
            message_type: Some("command_execution".to_string()),
            metadata: Some(json!({
                "kind": "runtime_agents_snapshot",
                "command": format!("python {}", learn::AGENTS_SCRIPT_FILENAME),
                "status": "started",
            })),
        });
    }

    let output = Command::new("python")
        .arg(learn::AGENTS_SCRIPT_FILENAME)
        .current_dir(workspace_dir)
        .output()
        .await
        .ok()?;

    if let Some(sender) = progress_sender.as_ref() {
        let _ = sender.send(JobMessage {
            content: format!("python {}", learn::AGENTS_SCRIPT_FILENAME),
            message_type: Some("command_execution".to_string()),
            metadata: Some(json!({
                "kind": "runtime_agents_snapshot",
                "command": format!("python {}", learn::AGENTS_SCRIPT_FILENAME),
                "status": if output.status.success() { "completed" } else { "failed" },
                "exitCode": output.status.code(),
            })),
        });
    }

    let mut combined = String::from_utf8_lossy(&output.stdout).to_string();
    if combined.trim().is_empty() {
        combined = String::from_utf8_lossy(&output.stderr).to_string();
    }
    if combined.trim().is_empty() {
        return None;
    }

    const MAX_BYTES: usize = 20_000;
    if combined.len() > MAX_BYTES {
        combined.truncate(MAX_BYTES);
        combined.push_str("\n[truncated]\n");
    }

    Some(combined.trim().to_string())
}

fn read_text_file_lossy_truncated(path: &Path, max_bytes: usize) -> Option<(String, bool)> {
    if max_bytes == 0 {
        return Some(("".to_string(), false));
    }
    let data = fs::read(path).ok()?;
    let truncated = data.len() > max_bytes;
    let slice = if truncated {
        &data[..max_bytes]
    } else {
        &data[..]
    };
    Some((String::from_utf8_lossy(slice).to_string(), truncated))
}

#[derive(Debug, Clone)]
struct SkillMetadata {
    name: Option<String>,
    description: Option<String>,
    context_kind: Option<String>,
    context_parents: Vec<String>,
    context_children: Vec<String>,
    routing_keywords: Vec<String>,
    always_include: bool,
    max_children: Option<usize>,
}

impl SkillMetadata {
    fn merge_defaults(&mut self, defaults: SkillMetadata) {
        if self.name.is_none() {
            self.name = defaults.name;
        }
        if self.description.is_none() {
            self.description = defaults.description;
        }
        if self.context_kind.is_none() {
            self.context_kind = defaults.context_kind;
        }
        if self.context_parents.is_empty() {
            self.context_parents = defaults.context_parents;
        }
        if self.context_children.is_empty() {
            self.context_children = defaults.context_children;
        }
        if self.routing_keywords.is_empty() {
            self.routing_keywords = defaults.routing_keywords;
        }
        if !self.always_include {
            self.always_include = defaults.always_include;
        }
        if self.max_children.is_none() {
            self.max_children = defaults.max_children;
        }
    }
}

fn normalize_skill_metadata_key(key: &str) -> String {
    key.trim()
        .to_ascii_lowercase()
        .replace(['_', '-'], "")
        .replace(' ', "")
}

fn parse_skill_metadata_list(value: &str) -> Vec<String> {
    let trimmed = value.trim().trim_matches('[').trim_matches(']').trim();
    if trimmed.is_empty() {
        return Vec::new();
    }

    trimmed
        .split(',')
        .map(|entry| entry.trim().trim_matches('"').trim_matches('\'').trim())
        .filter(|entry| !entry.is_empty())
        .map(|entry| entry.to_string())
        .collect()
}

fn parse_skill_metadata_bool(value: &str) -> Option<bool> {
    let normalized = value.trim().to_ascii_lowercase();
    match normalized.as_str() {
        "true" | "yes" | "1" => Some(true),
        "false" | "no" | "0" => Some(false),
        _ => None,
    }
}

fn parse_skill_metadata_usize(value: &str) -> Option<usize> {
    value.trim().parse::<usize>().ok()
}

fn apply_skill_metadata_field(out: &mut SkillMetadata, key: &str, value: &str) {
    let normalized_key = normalize_skill_metadata_key(key);
    let normalized_value = value
        .trim()
        .trim_matches('"')
        .trim_matches('\'')
        .trim()
        .to_string();
    if normalized_value.is_empty() {
        return;
    }
    let compact_value = normalized_value
        .split_whitespace()
        .collect::<Vec<_>>()
        .join(" ");

    match normalized_key.as_str() {
        "name" => out.name = Some(compact_value),
        "title" => {
            if out.name.is_none() {
                out.name = Some(compact_value);
            }
        }
        "description" => out.description = Some(compact_value),
        "applywhen" => {
            if out.description.is_none() {
                out.description = Some(compact_value);
            }
        }
        "contextkind" => out.context_kind = Some(compact_value),
        "contextparent" | "contextparents" | "parentcontext" | "parentcontexts" => {
            out.context_parents = parse_skill_metadata_list(normalized_value.as_str())
        }
        "contextchildren" | "childcontexts" => {
            out.context_children = parse_skill_metadata_list(normalized_value.as_str())
        }
        "routingkeywords" | "keywords" | "routingterms" => {
            out.routing_keywords = parse_skill_metadata_list(normalized_value.as_str())
        }
        "alwaysinclude" | "contextalwaysinclude" => {
            if let Some(value) = parse_skill_metadata_bool(normalized_value.as_str()) {
                out.always_include = value;
            }
        }
        "maxchildren" | "contextmaxchildren" => {
            out.max_children = parse_skill_metadata_usize(normalized_value.as_str())
        }
        _ => {}
    }
}

