    /// The refresh runs before a turn, before the scaffold writes anything
    /// into the checkout, and without a workspace lease it falls back to the
    /// origin's read-only refresh.
    #[test]
    fn a_turn_refreshes_the_checkout_before_the_scaffold_with_a_read_only_fallback() {
        // `run_apply_job` needs a runtime-sized stack, as in production.
        const STACK_SIZE: usize = 32 * 1024 * 1024;
        std::thread::Builder::new()
            .stack_size(STACK_SIZE)
            .spawn(|| {
                tokio::runtime::Builder::new_multi_thread()
                    .enable_all()
                    .worker_threads(2)
                    .thread_stack_size(STACK_SIZE)
                    .build()
                    .unwrap()
                    .block_on(turn_refreshes_before_the_scaffold())
            })
            .unwrap()
            .join()
            .unwrap();
    }

    async fn turn_refreshes_before_the_scaffold() {
        let tmp = tempdir().expect("temp dir");
        let base = test_job_processor(tmp.path());
        let mut config = (*base.config).clone();
        config.origin = Some(test_origin_settings(Some("http://127.0.0.1:9/project.git")));
        let processor = JobProcessor::new(Arc::new(config.clone()));
        let job = test_lease_job(None, json!({ "prompt_text": "/mcp list" }));
        let workspace = config.project_workspace_dir(&job.project_id.unwrap());

        let calls = Arc::new(std::sync::Mutex::new(Vec::<bool>::new()));
        let observed = Arc::clone(&calls);
        let scaffold = workspace.join(learn::INSTAFY_FILENAME);
        processor.set_local_origin_sync(Some(LocalOriginSync {
            origin_id: Uuid::new_v4(),
            endpoint: "http://127.0.0.1:9".to_string(),
            read_only_refresh: Some(crate::origin::ReadOnlyRefresh::new(move || {
                let observed = Arc::clone(&observed);
                let scaffold = scaffold.clone();
                async move {
                    observed.lock().unwrap().push(scaffold.exists());
                    Ok(json!({ "rev": "main", "checkoutMoved": true }))
                }
            })),
            working_state: None,
        }));

        let execution = processor
            .run_apply_job(
                &test_registration_with_proxy(),
                &job,
                true,
                None,
                None,
                None,
            )
            .await
            .expect("the mcp lane finishes");
        assert_eq!(execution.provider, "mcp");
        assert_eq!(
            *calls.lock().unwrap(),
            vec![false],
            "refreshed once, before the scaffold existed"
        );
        assert!(workspace.join(learn::INSTAFY_FILENAME).exists());

        // `/sync` publishes on its own; jobs that do not commit never refresh.
        let sync = test_lease_job(None, json!({ "prompt_text": "/sync" }));
        let _ = processor
            .run_apply_job(
                &test_registration_with_proxy(),
                &sync,
                true,
                None,
                None,
                None,
            )
            .await;
        let _ = processor
            .run_apply_job(
                &test_registration_with_proxy(),
                &job,
                false,
                None,
                None,
                None,
            )
            .await;
        assert_eq!(calls.lock().unwrap().len(), 1);
    }

    /// In a hosted checkout of a git-canonical space the controller's
    /// bootstrap keeps the bundled Instafy files: a turn that changes
    /// nothing leaves the folder as `main` has it, so no turn-end save keeps
    /// the runtime's own copies as unsaved work. A Desktop folder is still
    /// scaffolded.
    #[test]
    fn a_turn_leaves_a_canonical_checkout_as_main_has_it() {
        // `run_apply_job` needs a runtime-sized stack, as in production.
        const STACK_SIZE: usize = 32 * 1024 * 1024;
        std::thread::Builder::new()
            .stack_size(STACK_SIZE)
            .spawn(|| {
                tokio::runtime::Builder::new_multi_thread()
                    .enable_all()
                    .worker_threads(2)
                    .thread_stack_size(STACK_SIZE)
                    .build()
                    .unwrap()
                    .block_on(turn_leaves_a_canonical_checkout_as_main_has_it())
            })
            .unwrap()
            .join()
            .unwrap();
    }

    async fn turn_leaves_a_canonical_checkout_as_main_has_it() {
        for (mode, canonical) in [("hosted", true), ("efs", true), ("desktop", false)] {
            let tmp = tempdir().expect("temp dir");
            let base = test_job_processor(tmp.path());
            let mut config = (*base.config).clone();
            let mut origin = test_origin_settings(Some("http://127.0.0.1:9/project.git"));
            origin.mode = mode.to_string();
            config.origin = Some(origin);
            let processor = JobProcessor::new(Arc::new(config.clone()));
            let job = test_lease_job(None, json!({ "prompt_text": "/mcp list" }));
            let project_id = job.project_id.unwrap();
            let workspace = config.project_workspace_dir(&project_id);
            learn::commit_test_checkout(
                &workspace,
                "Add the team's notes",
                "someone@example.com",
                &[("notes.md", "# Notes\n")],
            );

            let execution = processor
                .run_apply_job(
                    &test_registration_with_proxy(),
                    &job,
                    true,
                    None,
                    None,
                    None,
                )
                .await
                .expect("the mcp lane finishes");
            assert_eq!(execution.provider, "mcp");
            // A multi-agent worker prepares the same folder.
            processor
                .prepare_workspace(&project_id)
                .expect("worker workspace");

            if canonical {
                assert_eq!(learn::test_checkout_status(&workspace), "", "{mode}");
                assert!(!workspace.join(learn::INSTAFY_FILENAME).exists(), "{mode}");
                assert!(
                    !workspace.join(learn::BOUND_SITES_RELATIVE_PATH).exists(),
                    "{mode}"
                );
            } else {
                assert!(workspace.join(learn::INSTAFY_FILENAME).exists());
                assert!(workspace.join(learn::BOUND_SITES_RELATIVE_PATH).exists());
            }
        }
    }

