    #[test]
    fn browser_turn_failures_read_as_plain_words() {
        // Studio shows a plain reason inline and keeps one that names the AI
        // vendor, a tool or the plumbing behind Details.
        for text in [
            SHARED_BROWSER_NO_PAGE_FAILURE,
            PERSONAL_BROWSER_NOT_USED_FAILURE,
            SHARED_BROWSER_NO_PAGE_RETRY_STATUS,
            PERSONAL_BROWSER_NOT_USED_RETRY_STATUS,
        ] {
            let lower = text.to_ascii_lowercase();
            for word in [
                "codex",
                "mcp",
                "tool",
                "instafy_",
                "shared browser",
                "personal browser",
                "evidence",
            ] {
                assert!(!lower.contains(word), "{text:?} names {word:?}");
            }
            assert!(
                text.starts_with("Octo ") || text.starts_with("Trying again: Octo "),
                "{text:?}"
            );
        }
    }

    #[test]
    fn terminal_shared_browser_consent_suppresses_retry_and_reprompt() {
        for code in ["approval_denied", "approval_timeout", "approval_stale"] {
            let events = vec![json!({
                "type": "item.completed",
                "item": {
                    "id": format!("call-{code}"),
                    "type": "mcp_tool_call",
                    "server": "instafy_shared_browser",
                    "tool": "click",
                    "status": "failed",
                    "terminalConsent": {
                        "state": "blocked",
                        "terminal": true,
                        "retryable": false,
                        "code": code,
                    }
                }
            })];
            let messages = extract_codex_messages(&events);
            let terminal = shared_browser_terminal_consent_failure(&messages);
            assert_eq!(terminal, Some(code));
            assert!(
                !should_retry_codex_once(terminal, true),
                "{code} unexpectedly allowed a second Codex attempt and retry prompt"
            );
            assert!(
                !shared_browser_execution_missing_after_attempt(
                    true,
                    &messages,
                    terminal,
                    Some(7),
                    7,
                ),
                "{code} was misreported as missing Shared Browser execution"
            );
            // The browser answered the click (the person said no, or did not
            // answer), so it is browser work even without its code.
            assert!(!shared_browser_execution_missing_after_attempt(
                true,
                &messages,
                None,
                Some(7),
                7,
            ));

            let expected = match code {
                "approval_denied" => {
                    "You said no, so that step didn't happen, and nothing from it was sent."
                }
                // Not a safety stop: the person said yes, and the page moved on.
                "approval_stale" => {
                    "The page changed after you said yes, so I didn't do that step. Send a message and I'll ask again."
                }
                _ => {
                    "I'm waiting for your OK to continue in Instafy's browser. I haven't done that step yet. Send a message when you're ready and I'll ask again."
                }
            };
            let mut summary = "internal no-final fallback".to_string();
            let mut fallback = Some(CodexFallbackSummaryKind::MissingFinalAssistantMessage);
            apply_terminal_shared_browser_summary(&mut summary, &mut fallback, terminal, false);
            assert_eq!(summary, expected);
            assert!(!summary.contains(code), "the person never reads {code}");
            assert_eq!(fallback, None);

            let mut false_success = "Done — the requested browser action succeeded.".to_string();
            let mut no_fallback = None;
            apply_terminal_shared_browser_summary(
                &mut false_success,
                &mut no_fallback,
                terminal,
                false,
            );
            assert_eq!(
                false_success, expected,
                "terminal consent must never preserve a false success summary"
            );
            assert_eq!(no_fallback, None);
        }

        // Every other terminal code reads the same plain message, without
        // the code, which stays in the terminal-consent artifact.
        for code in [
            "approval_stale_or_replayed",
            "approval_authority_revoked",
            "approval_storage_invalid",
            "approval_protocol_invalid",
            "approval_state_invalid",
            "approval_state_full",
        ] {
            let mut summary = "Done.".to_string();
            let mut fallback = None;
            apply_terminal_shared_browser_summary(&mut summary, &mut fallback, Some(code), true);
            assert_eq!(
                summary,
                "Instafy's browser stopped this step to keep it safe, so it wasn't done. Send a message to try again."
            );
            assert!(!should_retry_codex_once(Some(code), true));
        }

        assert!(should_retry_codex_once(None, true));
        assert!(!should_retry_codex_once(None, false));
    }

    /// A run whose browser went away (in a dogfood run the turn kept thinking
    /// for minutes) ends without a retry, and the person reads a plain message
    /// with no internal code.
    #[test]
    fn a_browser_that_went_away_ends_the_turn_with_a_plain_message() {
        let events = vec![json!({
            "type": "item.completed",
            "item": {
                "id": "call-browser-unavailable",
                "type": "mcp_tool_call",
                "server": "instafy_shared_browser",
                "tool": "snapshot",
                "status": "failed",
                "terminalConsent": {
                    "state": "blocked",
                    "terminal": true,
                    "retryable": false,
                    "code": "browser_unavailable",
                }
            }
        })];
        let messages = extract_codex_messages(&events);
        let terminal = shared_browser_terminal_consent_failure(&messages);
        assert_eq!(terminal, Some("browser_unavailable"));
        assert!(!should_retry_codex_once(terminal, true));
        assert!(!shared_browser_execution_missing_after_attempt(
            true,
            &messages,
            terminal,
            Some(7),
            7,
        ));
        let mut summary = "Still working on it.".to_string();
        let mut fallback = Some(CodexFallbackSummaryKind::MissingFinalAssistantMessage);
        apply_terminal_shared_browser_summary(&mut summary, &mut fallback, terminal, false);
        assert_eq!(
            summary,
            "Instafy's browser closed or stopped responding, so I stopped there. Open the browser again and send a message to continue."
        );
        assert_eq!(fallback, None);
    }

    /// A turn that pauses for the person's input right after Octo's last reply
    /// was such a pause says that the browser is still waiting. Let Octo
    /// continue pressed without signing in got the first pause's reply word for
    /// word, so the press looked as if it did nothing. The words hold on any
    /// page that pauses: a pause for a one-time code, a consent screen or a
    /// card form follows a sign-in the person did complete, with the same
    /// history, so they never claim the page is a sign-in page, and they keep
    /// saying that those details stay out of chat. A pause after any other
    /// reply, or in a chat with no history, reads as the first one does.
    #[test]
    fn a_pause_right_after_a_pause_says_the_browser_is_still_waiting() {
        let continue_prompt = "Continue the previous browser task on this same page. I may have used the browser while I had control. Take a fresh snapshot before acting; do not reuse old target indices or request, reveal, or repeat any values I may have entered.";
        let job = |history: JsonValue| {
            test_lease_job(Some("feature"), json!({ "conversation_history": history }))
        };
        let row = |role: &str, content: &str| json!({ "role": role, "content": content });
        let after_a_pause = job(json!([
            row(
                "user",
                "Open github.com, sign me in, then star the repository."
            ),
            row(
                "assistant",
                "Tool call completed: instafy_shared_browser/request_human_input"
            ),
            row("assistant", HUMAN_INPUT_PAUSE_REPLY),
            row("user", continue_prompt),
        ]));
        assert!(last_reply_was_a_pause(&after_a_pause));
        let mut summary = "The fresh snapshot still shows the sign-in page.".to_string();
        let mut fallback = None;
        apply_terminal_shared_browser_summary(
            &mut summary,
            &mut fallback,
            Some("human_input_required"),
            last_reply_was_a_pause(&after_a_pause),
        );
        assert_eq!(
            summary,
            "Instafy's browser is still waiting for you. Sign in or fill in the highlighted fields on the page, then choose Let Octo continue. I don't ask for those details in chat."
        );
        assert_ne!(summary, HUMAN_INPUT_PAUSE_REPLY);
        for claim in ["sign-in page", "Sign in there"] {
            assert!(!summary.contains(claim), "{claim}");
        }
        // A third press reads the same: the last reply was a pause too.
        let after_two = job(json!([
            row("assistant", HUMAN_INPUT_PAUSE_AGAIN_REPLY),
            row("user", continue_prompt),
        ]));
        assert!(last_reply_was_a_pause(&after_two));

        for first in [
            job(json!([row("user", "Open github.com and sign me in.")])),
            job(json!([
                row("assistant", "The shop is open daily from 09:00 to 19:30."),
                row("user", "Now sign me in to the shop."),
            ])),
            test_lease_job(Some("feature"), json!({})),
        ] {
            assert!(!last_reply_was_a_pause(&first));
            let mut summary = String::new();
            apply_terminal_shared_browser_summary(
                &mut summary,
                &mut None,
                Some("human_input_required"),
                last_reply_was_a_pause(&first),
            );
            assert_eq!(summary, HUMAN_INPUT_PAUSE_REPLY);
        }
    }

    /// Under routine browsing a turn opens pages and clicks before the step
    /// that asks, and the person may have allowed one risky step already. The
    /// summary of the step that then went unanswered or was declined speaks
    /// about that step only, never claims the turn changed nothing.
    #[test]
    fn terminal_shared_browser_summary_speaks_only_about_the_step_that_asked() {
        for code in [
            "approval_timeout",
            "approval_denied",
            "approval_stale",
            "approval_authority_revoked",
        ] {
            let mut events = ["navigate", "click"]
                .into_iter()
                .map(|tool| {
                    json!({
                        "type": "item.completed",
                        "item": {
                            "id": format!("call-{tool}"),
                            "type": "mcp_tool_call",
                            "server": "instafy_shared_browser",
                            "tool": tool,
                            "status": "completed",
                        }
                    })
                })
                .collect::<Vec<_>>();
            events.push(json!({
                "type": "item.completed",
                "item": {
                    "id": format!("call-{code}"),
                    "type": "mcp_tool_call",
                    "server": "instafy_shared_browser",
                    "tool": "click",
                    "status": "failed",
                    "terminalConsent": {
                        "state": "blocked",
                        "terminal": true,
                        "retryable": false,
                        "code": code,
                    }
                }
            }));
            let messages = extract_codex_messages(&events);
            assert!(has_successful_shared_browser_mcp_message(&messages));
            let terminal = shared_browser_terminal_consent_failure(&messages);
            assert_eq!(terminal, Some(code));

            let mut summary = "Opened the invoice and saved it.".to_string();
            let mut fallback = None;
            apply_terminal_shared_browser_summary(&mut summary, &mut fallback, terminal, false);
            let lowered = summary.to_lowercase();
            for whole_turn in ["nothing was", "nothing has", "no changes"] {
                assert!(
                    !lowered.contains(whole_turn),
                    "{code}: {summary:?} speaks about the whole turn"
                );
            }
            assert!(
                lowered.contains("that step") || lowered.contains("this step"),
                "{code}: {summary:?} does not name the step"
            );
            assert!(!summary.contains(code), "the person never reads {code}");
        }
    }

    #[test]
    fn terminal_consent_retry_signal_rejects_untrusted_or_malformed_metadata() {
        let message = |server: &str, terminal: bool, retryable: bool, code: &str| JobMessage {
            content: "Tool call failed".to_string(),
            message_type: Some("mcp_tool_call".to_string()),
            metadata: Some(json!({
                "server": server,
                "tool": "click",
                "status": "failed",
                "terminalConsent": {
                    "state": "blocked",
                    "terminal": terminal,
                    "retryable": retryable,
                    "code": code,
                }
            })),
        };

        assert_eq!(
            shared_browser_terminal_consent_failure(&[message(
                "another_server",
                true,
                false,
                "approval_denied"
            )]),
            None
        );
        assert_eq!(
            shared_browser_terminal_consent_failure(&[message(
                "instafy_shared_browser",
                true,
                true,
                "approval_denied"
            )]),
            None
        );
        assert_eq!(
            shared_browser_terminal_consent_failure(&[message(
                "instafy_shared_browser",
                false,
                false,
                "approval_denied"
            )]),
            None
        );
        assert_eq!(
            shared_browser_terminal_consent_failure(&[message(
                "instafy_shared_browser",
                true,
                false,
                "approval_fake"
            )]),
            None
        );
        assert_eq!(
            shared_browser_terminal_consent_failure(&[JobMessage {
                content: "[approval_denied_non_retryable]".to_string(),
                message_type: Some("mcp_tool_call".to_string()),
                metadata: Some(json!({
                    "server": "instafy_shared_browser",
                    "status": "failed",
                })),
            }]),
            None,
            "retry suppression must not parse prose"
        );
    }

