    #[test]
    fn has_successful_patch_apply_event_requires_completed_file_change() {
        let completed = json!({
            "type": "item.completed",
            "item": {
                "id": "call-1",
                "type": "file_change",
                "paths": ["docs/guide.md"],
                "status": "completed",
            }
        });
        let in_progress = json!({
            "type": "item.started",
            "item": {
                "id": "call-1",
                "type": "file_change",
                "paths": ["docs/guide.md"],
                "status": "in_progress",
            }
        });
        let failed = json!({
            "type": "item.completed",
            "item": {
                "id": "call-2",
                "type": "file_change",
                "paths": ["docs/guide.md"],
                "status": "failed",
            }
        });
        let command = json!({
            "type": "item.completed",
            "item": {
                "id": "call-3",
                "type": "command_execution",
                "command": "ls",
                "status": "completed",
            }
        });

        assert!(has_successful_patch_apply_event(&[
            in_progress.clone(),
            completed
        ]));
        assert!(!has_successful_patch_apply_event(&[in_progress, failed]));
        assert!(!has_successful_patch_apply_event(&[command]));
        assert!(!has_successful_patch_apply_event(&[]));
    }

