    fn test_progress() -> (
        JobProgress,
        tokio::sync::mpsc::UnboundedReceiver<JobMessage>,
    ) {
        let (sender, receiver) = tokio::sync::mpsc::unbounded_channel();
        (
            JobProgress {
                sender,
                status: Arc::new(AtomicBool::new(true)),
            },
            receiver,
        )
    }

    fn drain_types(receiver: &mut tokio::sync::mpsc::UnboundedReceiver<JobMessage>) -> Vec<String> {
        let mut types = Vec::new();
        while let Ok(message) = receiver.try_recv() {
            types.push(message.message_type.unwrap_or_default());
        }
        types
    }

    fn status_message(content: &str) -> JobMessage {
        JobMessage {
            content: content.to_string(),
            message_type: Some("status".to_string()),
            metadata: Some(json!({ "kind": "agent_message" })),
        }
    }

    /// A settled turn's cards follow its answer on the progress stream, ahead
    /// of the workspace sync's statuses, instead of waiting for the
    /// completion. What the controller acts on (a multi-agent plan), and
    /// everything after it, still posts with the completion.
    #[test]
    fn a_settled_turn_streams_its_cards_right_behind_its_answer() {
        let actions = vec![
            CodexAction::RequestSecret {
                name: "NOTION_TOKEN".to_string(),
                description: Some("Paste your Notion token.".to_string()),
                value_label: Some("Notion token".to_string()),
                where_to_get: None,
                skill: None,
                sensitive: Some(true),
                agent_handles: vec!["octo".to_string()],
                refused_class: None,
            },
            CodexAction::RequestLocation {
                precision: LocationPrecision::Approximate,
                description: None,
            },
            CodexAction::MultiAgentPlan {
                plan: json!({ "agents": [] }),
                agent_count: 2,
                rationale: None,
            },
            CodexAction::RequestSecret {
                name: "LATER_TOKEN".to_string(),
                description: None,
                value_label: None,
                where_to_get: None,
                skill: None,
                sensitive: Some(true),
                agent_handles: vec!["octo".to_string()],
                refused_class: None,
            },
        ];
        let final_messages = build_final_messages_from_actions(&actions, None);
        let (progress, mut receiver) = test_progress();
        progress
            .sender
            .send(status_message("/workspace"))
            .expect("the answer streams");

        let left = stream_settled_cards(Some(&progress), true, final_messages);
        progress
            .sender
            .send(status_message("Syncing workspace changes…"))
            .expect("the sync status streams");

        assert_eq!(
            drain_types(&mut receiver),
            vec!["status", "secret_request", "action_request", "status"],
            "the cards land right behind the answer, before the sync"
        );
        assert_eq!(
            left.iter()
                .map(|message| message.message_type.as_deref().unwrap_or_default())
                .collect::<Vec<_>>(),
            vec!["multi_agent_plan", "secret_request"],
            "the completion posts the plan and what follows it, in order"
        );
    }

    #[test]
    fn without_a_working_stream_the_completion_posts_every_card() {
        let cards = || {
            vec![
                JobMessage {
                    content: "Add the value in the card on this message.".to_string(),
                    message_type: Some("secret_request".to_string()),
                    metadata: None,
                },
                JobMessage {
                    content: "Connect Notion.".to_string(),
                    message_type: Some("integration_request".to_string()),
                    metadata: None,
                },
            ]
        };

        assert_eq!(stream_settled_cards(None, true, cards()).len(), 2);

        let (progress, mut receiver) = test_progress();
        assert_eq!(
            stream_settled_cards(Some(&progress), false, cards()).len(),
            2
        );
        progress.status.store(false, Ordering::SeqCst);
        assert_eq!(
            stream_settled_cards(Some(&progress), true, cards()).len(),
            2
        );
        assert!(drain_types(&mut receiver).is_empty());

        // The stream's sender is gone (its lease was lost): nothing is lost
        // here, the completion still holds every card.
        let (progress, receiver) = test_progress();
        drop(receiver);
        let left = stream_settled_cards(Some(&progress), true, cards());
        assert_eq!(
            left.iter()
                .map(|message| message.message_type.as_deref().unwrap_or_default())
                .collect::<Vec<_>>(),
            vec!["secret_request", "integration_request"]
        );
    }

    /// The routing pre-observation runs before Codex, so it streams first and
    /// the flush after Codex does not send it again.
    #[test]
    fn the_routing_pre_observation_streams_before_codex_and_only_once() {
        let observation = RoutingPreObservation {
            command: "pwd".to_string(),
            exit_code: Some(0),
            timed_out: false,
            output: "/workspace".to_string(),
        };
        let pre_observation = routing_pre_observation_message(&observation);
        let (progress, mut receiver) = test_progress();

        assert!(stream_routing_pre_observation(
            Some(&progress),
            Some(&pre_observation)
        ));
        // Codex runs and streams three messages, the last one not yet sent.
        let codex = vec![
            status_message("one"),
            status_message("two"),
            status_message("answer"),
        ];
        for message in &codex[..2] {
            progress.sender.send(message.clone()).expect("streams");
        }
        let mut interim = codex.clone();
        interim.push(pre_observation.clone());
        for message in interim_messages_to_flush(&interim, codex.len(), 2, true) {
            progress.sender.send(message.clone()).expect("flushes");
        }
        let mut sent = Vec::new();
        while let Ok(message) = receiver.try_recv() {
            sent.push(message.content);
        }
        assert_eq!(sent, vec!["pwd", "one", "two", "answer"]);

        // Not streamed before Codex (no working stream): the flush carries
        // it after Codex's messages, as it always did.
        assert_eq!(
            interim_messages_to_flush(&interim, codex.len(), 2, false)
                .iter()
                .map(|message| message.content.as_str())
                .collect::<Vec<_>>(),
            vec!["answer", "pwd"]
        );
        progress.status.store(false, Ordering::SeqCst);
        assert!(!stream_routing_pre_observation(
            Some(&progress),
            Some(&pre_observation)
        ));
        assert!(!stream_routing_pre_observation(
            None,
            Some(&pre_observation)
        ));
    }

    #[test]
    fn every_card_of_a_multi_value_turn_names_all_the_values() {
        // Seen on production: two cards, the Client-Id saved first, the
        // Client-Secret last. The last card's phrase named only its own value
        // and the agent concluded the Client-Id was still missing.
        let request = |name: &str, label: Option<&str>| CodexAction::RequestSecret {
            name: name.to_string(),
            description: None,
            value_label: label.map(str::to_string),
            where_to_get: None,
            skill: None,
            sensitive: None,
            agent_handles: vec!["octo".to_string()],
            refused_class: None,
        };
        let phrase = |message: &JobMessage| {
            message
                .metadata
                .as_ref()
                .and_then(|metadata| metadata.get("ui"))
                .and_then(|ui| ui.get("suggestedReply"))
                .and_then(JsonValue::as_str)
                .map(str::to_string)
        };

        let two = build_final_messages_from_actions(
            &[
                request("FREEFINANCE_API_CLIENT_ID", Some("Client-Id")),
                request("FREEFINANCE_API_CLIENT_SECRET", Some("Client-Secret")),
            ],
            None,
        );
        assert_eq!(two.len(), 2);
        for message in &two {
            assert_eq!(
                phrase(message).as_deref(),
                Some("I saved the Client-Id and the Client-Secret. Ready to continue.")
            );
        }

        let three = build_final_messages_from_actions(
            &[
                request("A_TOKEN", Some("API token")),
                request("A_SECRET", Some("secret")),
                request("A_REGION", Some("region")),
            ],
            None,
        );
        assert_eq!(
            phrase(&three[2]).as_deref(),
            Some("I saved the API token, the secret and the region. Ready to continue.")
        );

        // One card without a label makes it the plain plural.
        let unlabelled = build_final_messages_from_actions(
            &[
                request("A_TOKEN", Some("API token")),
                request("A_SECRET", None),
            ],
            None,
        );
        assert_eq!(
            phrase(&unlabelled[0]).as_deref(),
            Some("I saved the values. Ready to continue.")
        );

        // A single card keeps its own phrase.
        let one = build_final_messages_from_actions(&[request("A_TOKEN", Some("API token"))], None);
        assert_eq!(
            phrase(&one[0]).as_deref(),
            Some("I saved the API token. Ready to continue.")
        );
    }

    #[test]
    fn a_silent_model_still_gets_the_declaration_s_words_on_the_card() {
        // This is the failure the derivation exists for: the model sent the
        // name and nothing else, and the card read "Connect Notion / Add the
        // value in the card on this message.", which is worse than the
        // hardcoded catalogue entry it replaced.
        let dir = workspace_declaring_notion();
        let actions = vec![CodexAction::RequestSecret {
            name: "NOTION_API_KEY".to_string(),
            description: None,
            value_label: None,
            where_to_get: None,
            skill: None,
            sensitive: None,
            agent_handles: vec!["octo".to_string()],
            refused_class: None,
        }];

        let messages = build_final_messages_from_actions(&actions, Some(dir.path()));
        let details = secret_details(&messages);
        // The declared shape rides along, from the declaration and never the model.
        assert_eq!(
            details.get("valueHint").and_then(JsonValue::as_str),
            Some("ntn_")
        );
        assert_eq!(
            details.get("valueLabel").and_then(JsonValue::as_str),
            Some("Installation access token")
        );
        assert_eq!(
            details.get("description").and_then(JsonValue::as_str),
            Some("The Installation access token of an internal connection.")
        );
        assert_eq!(
            details.get("whereToGet").and_then(JsonValue::as_str),
            Some(
                "In the Notion developer portal, under Build, choose Internal connections, then Create a new connection."
            )
        );
        // The scan found the asker, so provenance reaches the card even though
        // the model named no skill.
        assert_eq!(
            details.get("skill").and_then(JsonValue::as_str),
            Some("notion")
        );
        assert_ne!(
            messages[0].content,
            "Add the value in the card on this message."
        );
    }

