    #[test]
    fn sensitive_takes_the_same_three_way_order() {
        let dir = workspace_declaring_notion();
        let request = |name: &str, sent: Option<bool>| CodexAction::RequestSecret {
            name: name.to_string(),
            description: None,
            value_label: None,
            where_to_get: None,
            skill: None,
            sensitive: sent,
            agent_handles: Vec::new(),
            refused_class: None,
        };
        let sensitive_of = |action: CodexAction| {
            secret_details(&build_final_messages_from_actions(
                &[action],
                Some(dir.path()),
            ))
            .get("sensitive")
            .and_then(JsonValue::as_bool)
            .expect("sensitive")
        };

        // The declaration's "No, optional" is read, where the old parse-site
        // default answered first and hid an optional value behind dots.
        assert!(!sensitive_of(request("NOTION_PAGE_ID", None)));
        // The model still outranks it.
        assert!(sensitive_of(request("NOTION_PAGE_ID", Some(true))));
        // And a value nobody labelled at all is still hidden.
        assert!(sensitive_of(request("SOME_OTHER_TOKEN", None)));
    }

    #[test]
    fn build_final_messages_writes_a_refusal_with_no_destination() {
        let actions = vec![CodexAction::RequestSecret {
            name: String::new(),
            description: Some("Your Notion account password works too.".to_string()),
            value_label: Some("Account password".to_string()),
            where_to_get: None,
            skill: Some("notion".to_string()),
            sensitive: Some(true),
            agent_handles: Vec::new(),
            refused_class: Some("password"),
        }];

        let messages = build_final_messages_from_actions(&actions, None);
        assert_eq!(messages.len(), 1);
        assert_eq!(
            messages[0].content,
            "A skill asked for a password. Instafy never takes one, and nothing has been saved."
        );
        let details = messages[0]
            .metadata
            .as_ref()
            .and_then(|metadata| metadata.get("details"))
            .and_then(JsonValue::as_object)
            .expect("details");
        assert_eq!(
            details.get("refusedClass").and_then(JsonValue::as_str),
            Some("password")
        );
        // No name, so no field, and none of the pack's words survive at all.
        assert!(details.get("name").is_none());
        assert!(details.get("valueLabel").is_none());
        assert!(details.get("description").is_none());
    }

    #[test]
    fn parse_codex_actions_supports_request_integration() {
        let payload = json!({
            "actions": [
                {
                    "type": "request_integration",
                    "provider": "Example",
                    "description": "Need Example access",
                    "requiredScopes": ["repo", "repo"],
                    "capabilities": ["issues.read", "issues.write"],
                    "authMethods": ["oauth", "secret"],
                    "suggestedSecrets": [
                        { "name": "EXAMPLE_TOKEN", "description": "Token from the Example dashboard settings." }
                    ],
                    "agentHandles": ["@octo", "octo", "claude"]
                }
            ]
        });

        let actions = parse_codex_actions(&payload);
        assert_eq!(actions.len(), 1);
        match &actions[0] {
            CodexAction::RequestIntegration {
                provider,
                description,
                required_scopes,
                capabilities,
                auth_methods,
                suggested_secret_names,
                suggested_secrets,
                agent_handles,
            } => {
                assert_eq!(provider, "example");
                assert_eq!(description.as_deref(), Some("Need Example access"));
                assert_eq!(required_scopes, &vec!["repo".to_string()]);
                assert_eq!(
                    capabilities,
                    &vec!["issues.read".to_string(), "issues.write".to_string()]
                );
                assert_eq!(
                    auth_methods,
                    &vec!["oauth".to_string(), "secret".to_string()]
                );
                assert_eq!(suggested_secret_names, &vec!["EXAMPLE_TOKEN".to_string()]);
                assert_eq!(suggested_secrets.len(), 1);
                assert_eq!(suggested_secrets[0].name, "EXAMPLE_TOKEN");
                assert_eq!(
                    suggested_secrets[0].description.as_deref(),
                    Some("Token from the Example dashboard settings.")
                );
                assert_eq!(
                    agent_handles,
                    &vec!["octo".to_string(), "claude".to_string()]
                );
            }
            _ => panic!("expected request integration action"),
        }
    }

